/* 案件一：實體證物、事實整理與不會卡死的判斷流程。 */
(function(){let seen=new Set();const room=()=>`<section class="room"><div class="shade"></div><header class="top"><div><b>案件一｜還沒賣出的大麻</b><br><small>深夜案件審查室</small></div></header>`;const end=()=>`</section>`;
function pop(x){modal(x)}function close(){closeModal()}
window.case1=function(){seen=new Set();app.innerHTML=room()+`<article class="panel folder-paper"><h2>案件一｜還沒賣出的大麻</h2><p class="notice">真實法律爭議改編</p><p>本案改編自司法院釋字第792號涉及的法律爭議，為教學需要簡化部分案情。</p><p>警方查獲陳○○持有一批大麻。他是否已經「販賣」毒品，仍需要進一步確認。</p><button class="primary" onclick="c1scene()">開始審查</button></article>`+end()};
window.c1scene=function(){app.innerHTML=room()+`<div class="case-head">先查看卷宗中的證物，釐清案件事實。</div><button class="obj bagobj" onclick="c1bag()" aria-label="透明證物袋"></button><button class="obj phoneobj" onclick="c1phone()" aria-label="被扣押的手機"></button><button class="obj recordobj" onclick="c1record()" aria-label="交易查核紀錄"></button>`+end()};
function done(x){seen.add(x);close();if(seen.size===3)setTimeout(c1facts,250)}
window.c1bag=function(){pop(`<h2>證物 A｜近拍</h2><div class="object-photo">🌿</div><p><b>鑑驗結果：大麻</b><br>列屬第二級毒品</p><button class="primary" onclick="c1done('bag')">記錄鑑驗結果</button>`) };window.c1phone=function(){pop(`<h2>被扣押的手機</h2><div class="chat"><div class="bubble me">陳○○：這批先放我這。</div><div class="bubble">友人：你自己要用的？</div><div class="bubble me">陳○○：不是啦。</div><div class="bubble me">陳○○：之後找到人再賣。</div><div class="bubble">友人：現在有人要嗎？</div><div class="bubble me">陳○○：還沒。</div></div><button class="primary" onclick="c1done('phone')">記錄關鍵事實</button>`) };window.c1record=function(){pop(`<h2>交易查核紀錄</h2><p>已確認買家：未發現<br>成交紀錄：未發現<br>收款紀錄：未發現</p><button class="primary" onclick="c1done('record')">記錄查核結果</button>`) };window.c1done=done;
window.c1facts=function(){app.innerHTML=room()+`<article class="fact-sheet"><h2>案件事實</h2><p>① 查扣物為大麻，列屬第二級毒品<br><small>來源：證物鑑驗</small></p><p>② 陳○○有將毒品轉賣的意圖<br><small>來源：手機通訊紀錄</small></p><p>③ 尚未發現買家、成交及收款紀錄<br><small>來源：交易查核</small></p><button class="primary" onclick="c1law()">繼續</button></article>`+end()};
window.c1law=function(){pop(`<p>他準備把毒品賣掉，但目前沒有發現已完成的交易。</p><h2>法律上的「販賣」已經成立了嗎？</h2><button class="primary" onclick="closeModal();c1code()">查看桌上的《法規資料》</button>`)};
window.c1code=function(){app.innerHTML=room()+`<article class="panel folder-paper"><h2>《毒品危害防制條例》</h2><p class="law-text"><b>第4條第2項</b><br>製造、運輸、販賣第二級毒品者，處無期徒刑或十年以上有期徒刑，得併科新臺幣一千五百萬元以下罰金。</p><p class="law-text"><b>第5條第2項</b><br>意圖販賣而持有第二級毒品者，處五年以上有期徒刑，得併科新臺幣五百萬元以下罰金。</p><button class="primary" onclick="c1initialDecisionV2()">作成初步判斷</button></article>`+end()};
window.c1judge=function(){pop(`<h2>依目前查得的案件事實，你會先依哪一條規定處理？</h2><button class="choice" onclick="c1alert()">第5條第2項</button><button class="choice" onclick="c1alert()">第4條第2項</button>`) };window.c1alert=function(){close();pop(`<h2>你的初步判斷已記錄。</h2><p>喀——</p><p class="notice">⚠ 發現不同見解</p><p>但是，過去法官的見解，和你的判斷不一樣。</p><button class="primary" onclick="c1old()">查看過去實務</button>`) };window.c1old=function(){close();pop(`<article class="old-paper"><h2>過去實務</h2><p>過去實務曾認為：若行為人基於營利目的購入毒品，即使尚未完成出售，也可能被認定構成「販賣」。</p><p>第4條第2項：無期或十年以上，最高併科1,500萬元<br>第5條第2項：五年以上，最高併科500萬元</p><p>同一組案件事實，為什麼可能適用不同的條文？<br><br>關鍵可能就在——「販賣」這兩個字，應該怎麼理解？</p><button class="primary" onclick="closeModal();c1word()">檢查「販賣」的意思</button></article>`) };
window.c1word=function(){pop(`<h2>「販賣」的文字意義</h2><p>如果只從「販賣」這個詞本身理解，哪一個行為最不能被拿掉？</p>${['購入','持有','出售','轉售'].map(x=>`<button class="choice" onclick="${x==='出售'?'c1wordok()':'c1wrong()'}">${x}</button>`).join('')}`)};window.c1wrong=function(){close();pop(`<p>再想想：這個行為可能和「販賣」有關，但如果完全沒有「賣」的行為，還能直接說已經完成「販賣」嗎？</p><button class="primary" onclick="closeModal();c1word()">再想想</button>`)};window.c1wordok=function(){close();pop(`<h2>🔍 文義線索</h2><p>你剛才是從法律文字本身可能具有的意義，判斷「販賣」的範圍。</p><p>這種方法稱為「文義解釋」。</p><button class="primary" onclick="closeModal();system1()">繼續</button>`)};
})();
